// ---- src/bbm-images.js
const { teamFile, logoPath, teamColor, normalizeName, espnIdFor, headshotURL, initials, headshot, teamLogo, logoURL, enhanceTables, enhanceCards, enhanceGames, enhanceAll } = (() => {
// Team logos (bundled) and player headshots (ESPN CDN) for BBM pages.
// Logos resolve from the team abbreviation in each row. Headshots resolve
// from the ESPN id map in bbm-espn.js; unknown players get an initials chip.


// BBM abbreviations that differ from the ESPN file names.
const TEAM_FILE = { GSW: "gs", NOR: "no", SAS: "sa", UTA: "utah", WAS: "wsh", NYK: "ny", PHO: "phx" };

// Display names ESPN spells differently from BBM.
const ALIASES = { "Alexandre Sarr": "Alex Sarr", "Trey Murphy": "Trey Murphy III" };

function teamFile(abbrev) {
  const key = String(abbrev || "").trim().toUpperCase();
  if (!key || key === "FA") return null;
  return (TEAM_FILE[key] || key.toLowerCase()) + ".png";
}

function logoPath(abbrev) {
  const file = teamFile(abbrev);
  return file ? `src/assets/nba/${file}` : null;
}

// Primary brand colour per bundled logo file, used for the schedule day tint.
// Each value is the dominant saturated colour of that logo, measured with a
// canvas read of the bundled PNG rather than hand-picked from brand guides.
const TEAM_COLOR = {
  atl: "#eb2342", bkn: "#808080", bos: "#018442", cha: "#3a2d75", chi: "#c30936",
  cle: "#a00938", dal: "#014f8f", den: "#031f40", det: "#ed3752", gs: "#03418b",
  hou: "#cf112d", ind: "#0f2641", lac: "#19214b", lal: "#dea40e", mem: "#273d6c",
  mia: "#8d0022", mil: "#24613d", min: "#395b97", no: "#162d49", ny: "#d77b26",
  okc: "#355181", orl: "#3964a6", phi: "#00408d", phx: "#ca4f0e", por: "#a22326",
  sa: "#747b7d", sac: "#764091", tor: "#f00940", utah: "#502c86", wsh: "#0c3064",
};

function teamColor(abbrev) {
  const file = teamFile(abbrev);
  return file ? TEAM_COLOR[file.replace(/\.png$/, "")] || null : null;
}

function normalizeName(name) {
  return String(name || "")
    .replace(/\./g, "")
    .replace(/\s+/g, " ")
    .replace(/\s+(III|IV|II|Jr|Sr|V)$/i, "")
    .trim();
}

const normalizedIds = new Map(Object.entries(ESPN_IDS).map(([name, id]) => [normalizeName(name), id]));

function espnIdFor(name) {
  if (!name) return null;
  const clean = String(name).trim();
  if (ESPN_IDS[clean] != null) return ESPN_IDS[clean];
  const alias = ALIASES[clean];
  if (alias && ESPN_IDS[alias] != null) return ESPN_IDS[alias];
  return normalizedIds.get(normalizeName(clean)) ?? null;
}

function headshotURL(id) {
  return id == null ? null : `https://a.espncdn.com/i/headshots/nba/players/full/${id}.png`;
}

function initials(name) {
  const parts = String(name || "").trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  return (parts[0][0] + (parts.length > 1 ? parts.at(-1)[0] : "")).toUpperCase();
}

const assetURL = (path) => {
  try {
    if (typeof chrome !== "undefined" && chrome.runtime?.getURL) return chrome.runtime.getURL(path);
  } catch { /* the audit harness has no chrome runtime; fall through */ }
  try {
    return new URL(path.replace(/^src\//, ""), import.meta.url).href;
  } catch {
    return path;
  }
};

function chipFor(className, label, fallbackText) {
  const chip = document.createElement("span");
  chip.className = `${className} cgm-fallback`;
  chip.textContent = fallbackText;
  chip.title = label || "";
  chip.setAttribute("aria-hidden", "true");
  return chip;
}

function image(source, className, label, fallbackText) {
  if (source == null || source === "") {
    return fallbackText ? chipFor(className, label, fallbackText) : null;
  }
  const img = document.createElement("img");
  img.className = className;
  img.src = source;
  img.alt = "";
  img.loading = "lazy";
  img.decoding = "async";
  img.setAttribute("aria-hidden", "true");
  if (fallbackText) {
    img.title = label || "";
    img.addEventListener("error", () => {
      img.replaceWith(chipFor(className, label, fallbackText));
    }, { once: true });
  } else {
    img.addEventListener("error", () => img.remove(), { once: true });
  }
  return img;
}

function headshotFor(name) {
  return image(headshotURL(espnIdFor(name)), "cgm-head", name, initials(name));
}

// Big headshot for the playerinfo hero. Same source and initials fallback as
// the inline chips, only the size class differs.
function headshot(name, cls = "cgm-head") {
  return image(headshotURL(espnIdFor(name)), cls, name, initials(name));
}

function teamLogo(abbrev, cls = "cgm-logo") {
  const logo = logoFor(abbrev);
  if (logo) logo.className = cls;
  return logo;
}

// Resolved URL of the bundled logo, for use as a CSS background image.
function logoURL(abbrev) {
  const path = logoPath(abbrev);
  return path ? assetURL(path) : null;
}

function logoFor(abbrev) {
  const path = logoPath(abbrev);
  if (!path) return null;
  return image(assetURL(path), "cgm-logo", String(abbrev).trim().toUpperCase(), null);
}

function tagPlayer(link) {
  if (!link || link.dataset.cgmImg) return;
  link.dataset.cgmImg = "1";
  const name = link.textContent.trim();
  const chip = document.createElement("span");
  chip.className = "cgm-id";
  link.before(chip);
  chip.append(headshotFor(name), link);
}

function tagTeam(cell) {
  if (!cell || cell.dataset.cgmImg) return;
  const logo = logoFor(cell.textContent);
  if (!logo) return;
  cell.dataset.cgmImg = "1";
  cell.prepend(logo);
}

function enhanceTables(root = document) {
  for (const table of root.querySelectorAll("table")) {
    if (!table.querySelector('a[href*="playerinfo.aspx" i], a[href*="playerInfo.aspx"]')) continue;
    for (const row of table.rows) {
      if ([...row.children].every((cell) => cell.tagName === "TH")) continue;
      const link = row.querySelector('a[href*="playerinfo.aspx" i], a[href*="playerInfo.aspx"]');
      if (!link) continue;
      tagPlayer(link);
      // The rankings grid puts the team in the cell after the name. The box
      // score table puts the position there, and its own team cell further
      // along, so the cell is found by the abbreviation it holds rather than
      // by its position in the row: a position is not one of the teams the
      // redesign has a logo for.
      const cells = [...row.children];
      const at = cells.findIndex((cell) => cell.contains(link));
      const team = cells.slice(at + 1).find((cell) => cell.classList.contains("tdc") && teamColor(cell.textContent.trim()));
      if (team) tagTeam(team);
    }
  }
}

function enhanceCards(root = document) {
  for (const holder of root.querySelectorAll(".display-player")) {
    const link = holder.querySelector(".display-player-name");
    if (link) tagPlayer(link);
    else if (!holder.dataset.cgmImg && holder.querySelector("a")) tagPlayer(holder.querySelector("a"));
    const team = holder.querySelector(".display-player-team");
    if (team && !team.dataset.cgmImg) {
      const logo = logoFor(team.textContent);
      if (logo) { team.dataset.cgmImg = "1"; team.prepend(logo); }
    }
  }
}

function enhanceGames(root = document) {
  for (const box of root.querySelectorAll(".daily-status-updates")) {
    for (const span of box.querySelectorAll(".daily-status-updates-teams span")) {
      if (span.dataset.cgmImg || span.querySelector("img")) continue;
      const logo = logoFor(span.textContent);
      if (logo) { span.dataset.cgmImg = "1"; span.prepend(logo); }
    }
    for (const link of box.querySelectorAll('a[href*="playerinfo.aspx" i], a[href*="playerInfo.aspx"]')) tagPlayer(link);
  }
}

let watching = false;

function enhanceAll(root = document) {
  enhanceTables(root);
  enhanceCards(root);
  enhanceGames(root);
  if (watching || root !== document || !document.body) return;
  watching = true;
  let queued = false;
  new MutationObserver(() => {
    if (queued) return;
    queued = true;
    setTimeout(() => { queued = false; enhanceAll(); }, 300);
  }).observe(document.body, { childList: true, subtree: true });
}
return { teamFile, logoPath, teamColor, normalizeName, espnIdFor, headshotURL, initials, headshot, teamLogo, logoURL, enhanceTables, enhanceCards, enhanceGames, enhanceAll };
})();

// ---- src/bbm-boxsheet.js
const { gameSection, gameTable, gamePlayers, analystComments, openBox } = (() => {
// The box score sheet: the game's own table from the Box Scores page the NBA
// Today tab already holds, and the site's own analyst comments about the
// players in it. The table is the site's own markup, so it keeps the site's
// columns; the links that would post back to the Box Scores page are removed,
// because this sheet sits on the home page's form.
//
// The analyst comments live on the site's Live Results page, one per player, in
// the last column of its table: the comment itself is the tooltip's title and
// the analyst's name sits beside the mark. The comments the community leaves
// are on a different page and are not what a reader wants beside a box score.




const RESULTS_URL = "dailysummary.aspx";
const RESULTS_KEY = "cgmBbmSheetAnalysts";
const RESULTS_TTL = 10 * 60 * 1000;

const div = (className, ...nodes) => {
  const box = Object.assign(document.createElement("div"), { className });
  box.append(...nodes.filter(Boolean));
  return box;
};

// The card's own text, without its markup.
const plain = (html) => String(html)
  .replace(/<[^>]+>/g, " ")
  .replace(/&(amp|lt|gt|quot|#39|#x27);/g, (match) => ({ "&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&#39;": "'", "&#x27;": "'" }[match] || match))
  .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
  .replace(/\s+/g, " ")
  .trim();

// The Box Scores page holds one section per game: an anchor, the game's
// heading, and the player's table.
function gameSection(html, anchor) {
  const page = String(html);
  const at = page.indexOf(`<a name='${anchor}'`);
  if (at < 0) return null;
  const next = page.indexOf("<a name='", at + 12);
  return page.slice(at, next < 0 ? page.length : next);
}

// The game's table, in the site's own markup.
function gameTable(section) {
  const match = String(section).match(/<table[^>]*class=['"][^'"]*modern-stats-table[^'"]*['"][^>]*>([\s\S]*?)<\/table>/);
  return match ? match[0] : null;
}

// The players in a game's table, with the id the site links them by.
function gamePlayers(table) {
  return [...String(table).matchAll(/playerinfo\.aspx\?i=(\d+)[^>]*>([^<]+)</gi)]
    .map((match) => ({ id: match[1], name: plain(match[2]) }));
}

// The Live Results page's analyst comments: one row per player, with the
// comment in the last cell. The comment is the tooltip's title and the age
// sits in its brackets; the analyst's name sits beside the mark.
function analystComments(html) {
  const comments = [];
  for (const row of String(html).matchAll(/<tr class=''>([\s\S]*?)<\/tr>/g)) {
    const cells = [...row[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map((match) => match[1]);
    const player = row[1].match(/playerinfo\.aspx\?i=(\d+)[^>]*>([^<]+)</i);
    if (!player || cells.length < 2) continue;
    const mark = cells[cells.length - 1].match(/title="([^"]+)"[\s\S]*?<i class="far fa-square">[\s\S]*?<\/i>\s*<\/span>&#160;([^<]*)</);
    if (!mark) continue;
    const age = mark[1].match(/\((\d+(?:\.\d+)?[dhmy])\)\s*$/);
    const at = cells.findIndex((cell) => /playerinfo\.aspx/i.test(cell));
    comments.push({
      id: player[1],
      name: plain(player[2]),
      team: at >= 0 ? plain(cells[at + 1]) : null,
      comment: (age ? mark[1].slice(0, age.index) : mark[1]).trim(),
      analyst: plain(mark[2]),
      age: age ? age[1] : null,
    });
  }
  return comments;
}

// The table's header cells carry links that post back to the Box Scores page.
// The title attribute still carries the column's explanation. The value holds
// quotes of its own, so each quote style is matched on its own.
const inert = (html) => html
  .replace(/\shref='javascript:[^']*'/g, "")
  .replace(/\shref="javascript:[^"]*"/g, "");

const scoreLine = (game) => {
  const points = (side) => (side.score == null ? "" : ` ${side.score}`);
  return `${game.away.team}${points(game.away)} @ ${game.home.team}${points(game.home)}`;
};

// One analyst comment: the player, the analyst, how long ago, and the comment.
function analystCard(comment) {
  const row = div("cgm-analyst");
  const head = div("cgm-analyst-head");
  const player = div("cgm-analyst-player");
  const logo = teamLogo(comment.team, "cgm-logo cgm-analyst-logo");
  if (logo) player.append(logo);
  player.append(document.createTextNode(comment.name));
  head.append(player, div("cgm-analyst-meta", [comment.analyst, comment.age].filter(Boolean).join(" · ")));
  row.append(head, div("cgm-analyst-body", comment.comment));
  return row;
}

const readCache = () => {
  try {
    const cached = JSON.parse(sessionStorage.getItem(RESULTS_KEY));
    return cached && Date.now() - cached.at < RESULTS_TTL ? cached.comments : null;
  } catch { return null; }
};

// The Live Results page, once per tab per ten minutes.
async function loadAnalysts() {
  const cached = readCache();
  if (cached) return cached;
  // The page is only readable from the site's own origin.
  if (new URL(RESULTS_URL, location.href).origin !== location.origin) return [];
  const response = await fetch(pageURL(RESULTS_URL), { credentials: "same-origin" });
  if (!response.ok) throw new Error(`the live results page answered ${response.status}`);
  const comments = analystComments(await response.text());
  try { sessionStorage.setItem(RESULTS_KEY, JSON.stringify({ at: Date.now(), comments })); } catch { /* storage blocked */ }
  return comments;
}

// Open the box score sheet for a game. The board is the Box Scores page the
// tab already holds, so the table costs no request of its own.
function openBox(game, board, opener) {
  const section = gameSection(board, game.anchor);
  const table = section && gameTable(section);
  if (!table) return null;

  const overlay = document.createElement("div");
  overlay.className = "cgm-overlay";
  const sheet = document.createElement("div");
  sheet.className = "cgm-sheet cgm-sheet--box";
  sheet.setAttribute("role", "dialog");
  sheet.setAttribute("aria-modal", "true");
  sheet.setAttribute("aria-label", `Box score ${game.away.team} at ${game.home.team}`);
  const head = document.createElement("div");
  head.className = "cgm-sheet-head";
  const title = Object.assign(document.createElement("span"), { className: "cgm-sheet-title", textContent: scoreLine(game) });
  const close = Object.assign(document.createElement("button"), { type: "button", className: "cgm-sheet-close", textContent: "Close" });
  head.append(title, close);
  const body = document.createElement("div");
  body.className = "cgm-box-body";
  const tableBox = document.createElement("div");
  tableBox.className = "cgm-box-table";
  tableBox.innerHTML = inert(table);
  const notes = document.createElement("div");
  notes.className = "cgm-box-notes";
  body.append(tableBox, notes);
  sheet.append(head, body);
  overlay.append(sheet);
  document.body.append(overlay);

  // The table becomes a board like every other table on the site: its own
  // scroller, a sticky header and a sticky name column.
  buildBoards();
  enhanceTables(tableBox);
  paintBoards();

  const ids = new Set(gamePlayers(table).map((player) => player.id));
  const show = (heading, list, back) => {
    notes.replaceChildren();
    const label = div("cgm-box-notes-head", heading);
    if (back) {
      const again = Object.assign(document.createElement("button"), { type: "button", className: "cgm-show-all", textContent: "← All this game's players" });
      again.addEventListener("click", back);
      label.append(again);
    }
    notes.append(label);
    if (!list.length) {
      notes.append(div("cgm-box-empty", "No analyst comment for these players."));
      return;
    }
    for (const comment of list) notes.append(analystCard(comment));
  };

  const gameNotes = async () => {
    try {
      const comments = await loadAnalysts();
      show("Analyst comments on this game's players", comments.filter((comment) => ids.has(comment.id)));
    } catch (error) {
      console.error("ClutchGM could not read the live results page", error);
      show("Analyst comments on this game's players", []);
    }
  };

  // A player in the table opens that player's own analyst comment.
  for (const link of tableBox.querySelectorAll("a[href*='playerinfo.aspx' i]")) {
    link.addEventListener("click", (event) => {
      event.preventDefault();
      const id = new URL(link.href, location.href).searchParams.get("i");
      if (!id) return;
      const name = link.textContent.trim();
      show(`Analyst comment on ${name}`, []);
      loadAnalysts().then(
        (comments) => show(`Analyst comment on ${name}`, comments.filter((comment) => comment.id === id), () => gameNotes()),
        (error) => {
          console.error("ClutchGM could not read the live results page", error);
          show(`Analyst comment on ${name}`, [], () => gameNotes());
        },
      );
    });
  }

  const hide = () => {
    overlay.hidden = true;
    document.documentElement.classList.remove("cgm-lock");
    overlay.remove();
    opener?.focus();
  };
  close.addEventListener("click", hide);
  overlay.addEventListener("click", (event) => { if (event.target === overlay) hide(); });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !overlay.hidden) hide();
  });
  overlay.hidden = false;
  document.documentElement.classList.add("cgm-lock");
  close.focus();
  gameNotes();
  return overlay;
}
return { gameSection, gameTable, gamePlayers, analystComments, openBox };
})();

// ---- src/bbm-today.js
const { scoreCell, gameState, todayBoard, boardDate, boardNumber, todayNumber, renderToday } = (() => {
// NBA Today: the day's NBA games with their live scores, read from the site's
// own Box Scores page. The board that page serves is the latest day it holds
// results for, and the day is moved with the site's own Next and Back buttons.
// A day with no games has no board at all, and that is said plainly instead of
// shown as an empty list.




const BOARD = "boxscores.aspx";
const REFRESH_MS = 2 * 60 * 1000;
const MAX_JUMP = 31;
const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

const div = (className, ...nodes) => {
  const box = Object.assign(document.createElement("div"), { className });
  box.append(...nodes.filter(Boolean));
  return box;
};

// The cell text without its markup.
const text = (html) => String(html)
  .replace(/<[^>]+>/g, " ")
  .replace(/&#160;|&nbsp;/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/\s+/g, " ")
  .trim();

// One side of a game reads "MIL 128", and the home side carries the mark that
// says the game is played there: "@ IND 127".
function scoreCell(value) {
  const match = String(value).trim().match(/^@?\s*([A-Z]{2,3})\s*(\d{1,3})?$/);
  if (!match) return null;
  return { team: match[1], score: match[2] == null ? null : Number(match[2]) };
}

// The status cell says the game's state in the site's own words, and its
// progress bar says how much of the game is played.
function gameState(value) {
  const label = text(value);
  const bar = String(value).match(/aria-valuenow="(\d+)"/);
  const percent = bar ? Number(bar[1]) : null;
  if (/^final$/i.test(label)) return { state: "final", label: "Final", percent: 100 };
  if (percent != null && percent > 0) return { state: "live", label: label || "Live", percent };
  return { state: "scheduled", label: label || "Scheduled", percent: percent ?? 0 };
}

// The board is the table whose head reads Away / Home / Time / Status. It
// holds no nested table, so the first closing tag after the head is its own.
// A day without games has no such table, so the page carries no board at all.
function todayBoard(html) {
  const page = String(html);
  const head = /<th[^>]*>\s*Away\s*<\/th>/.exec(page);
  if (!head) return null;
  const start = page.lastIndexOf("<table", head.index);
  const end = page.indexOf("</table>", head.index);
  if (start < 0 || end < 0) return null;
  const games = [];
  // The head row is not closed on the site, so the rows are split on their
  // opening tag rather than on a closing one.
  for (const row of page.slice(start, end).split(/<tr[\s>]/).slice(1)) {
    const cells = [...row.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map((match) => match[1]);
    if (cells.length < 5) continue;
    const away = scoreCell(text(cells[1]));
    const home = scoreCell(text(cells[2]));
    if (!away || !home) continue;
    games.push({
      away,
      home,
      time: text(cells[3]),
      status: gameState(cells[4]),
      anchor: (cells[0].match(/href='#([^']+)'/) || [])[1] || null,
    });
  }
  return { games };
}

// The calendar paints the day on show in SteelBlue, and that cell's link names
// the date. The month header carries the year.
function boardDate(html) {
  const page = String(html);
  const at = page.indexOf("background-color:SteelBlue");
  if (at < 0) return null;
  const day = page.slice(at, at + 400).match(/title="([A-Za-z]+) (\d{1,2})"/);
  if (!day) return null;
  const month = MONTHS.indexOf(day[1]);
  if (month < 0) return null;
  const year = [...page.matchAll(/<td[^>]*>\s*([A-Za-z]+)\s+(\d{4})\s*<\/td>/g)]
    .find((match) => MONTHS.indexOf(match[1]) === month);
  if (!year) return null;
  const number = Number(day[2]);
  const weekday = WEEKDAYS[new Date(Date.UTC(Number(year[2]), month, number)).getUTCDay()];
  return { label: `${weekday}, ${day[1]} ${number}`, month: day[1], number, year: Number(year[2]) };
}

// A day as a day number, so the distance between two days is a subtraction.
const dayNumber = (year, month, date) => Date.UTC(year, month, date) / 86400000;
const boardNumber = (date) => dayNumber(date.year, MONTHS.indexOf(date.month), date.number);

// The board's days are Eastern, so today is read in that timezone.
function todayNumber() {
  const parts = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", year: "numeric", month: "numeric", day: "numeric" }).formatToParts(new Date());
  const get = (type) => Number(parts.find((part) => part.type === type).value);
  return dayNumber(get("year"), get("month") - 1, get("day"));
}

// One game: both sides with their logos, the scores, the tip time and the
// state. The side ahead is underlined, the way the live match board marks a
// leader. The time, the state and the box score link travel together, so a
// narrow window drops them as one row.
function gameRow(game, onBox) {
  const row = div("cgm-today-game");
  const ahead = game.away.score != null && game.home.score != null && game.away.score !== game.home.score
    ? (game.away.score > game.home.score ? game.away : game.home)
    : null;
  const team = (side, host) => {
    const mark = div("cgm-today-team");
    const logo = teamLogo(side.team, "cgm-logo cgm-today-logo");
    const name = document.createTextNode(side.team);
    const value = div("cgm-today-score", side.score == null ? "–" : String(side.score));
    if (ahead === side) value.classList.add("cgm-ahead");
    mark.append(...(host ? [name, value, logo] : [logo, name, value]).filter(Boolean));
    return mark;
  };
  const meta = div("cgm-today-meta");
  meta.append(div("cgm-today-time", game.time), div(`cgm-today-state cgm-today-state--${game.status.state}`, game.status.label));
  if (game.status.state === "live") {
    const fill = div("cgm-today-progress-fill");
    fill.style.width = `${game.status.percent}%`;
    meta.append(div("cgm-today-progress", fill));
  }
  if (game.anchor) {
    // The box score opens over the tab, so the reader keeps the board behind
    // it and the sheet closes back onto the row they came from.
    const box = Object.assign(document.createElement("button"), { type: "button", className: "cgm-today-box", textContent: "Box" });
    box.addEventListener("click", () => onBox(game, box));
    meta.append(box);
  }
  row.append(team(game.away, false), div("cgm-today-at", "@"), team(game.home, true), meta);
  return row;
}

function renderToday(panel) {
  const when = div("cgm-panelhead-title", "Loading the day's games…");
  const stamp = div("cgm-today-stamp", "Not updated yet");
  const refresh = Object.assign(document.createElement("button"), { type: "button", className: "cgm-show-all", textContent: "Refresh" });
  const back = Object.assign(document.createElement("button"), { type: "button", className: "cgm-today-step", textContent: "‹", title: "Previous day" });
  back.setAttribute("aria-label", "Previous day");
  const next = Object.assign(document.createElement("button"), { type: "button", className: "cgm-today-step", textContent: "›", title: "Next day" });
  next.setAttribute("aria-label", "Next day");
  const today = Object.assign(document.createElement("button"), { type: "button", className: "cgm-show-all", textContent: "Today" });
  // The same head row as every other surface: the day and its controls on the
  // left, the stamp on the right.
  const bar = div("cgm-panelhead");
  bar.append(div("cgm-panelhead-left", when, back, next, today, refresh), stamp);
  const list = div("cgm-today-list");
  panel.append(bar, list);

  let html = "";
  const stampNow = () => {
    stamp.textContent = `Updated ${new Date().toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}`;
  };
  const paint = (page) => {
    const date = boardDate(page);
    const board = todayBoard(page);
    when.textContent = date ? date.label : "NBA Today";
    today.disabled = !date || boardNumber(date) === todayNumber();
    list.replaceChildren();
    if (!board || !board.games.length) {
      list.append(div("cgm-today-empty", date ? `No games on ${date.label}.` : "No games to show."));
      return;
    }
    for (const game of board.games) list.append(gameRow(game, (row, opener) => openBox(row, html, opener)));
  };
  const fail = (error) => {
    console.error("ClutchGM could not read the NBA Today board", error);
    (window.__cgmErrors ||= []).push(`today: ${error.message}`);
    stamp.textContent = "Could not read the Box Scores page";
    if (!list.children.length) list.append(div("cgm-today-empty", "Could not read the Box Scores page."));
  };

  const load = async () => {
    const response = await fetch(pageURL(BOARD), { credentials: "same-origin" });
    if (!response.ok) throw new Error(`the box scores page answered ${response.status}`);
    html = await response.text();
    paint(html);
    stampNow();
  };
  // The site's own Next and Back buttons move the board one day at a time.
  const move = (direction) => postFields(pageURL(BOARD), hiddenFields(html), direction === "next" ? { NEXT: "Next" } : { BACK: "Back" });
  const step = async (direction) => {
    if (!html) return;
    html = await move(direction);
    paint(html);
    stampNow();
  };
  // Today is a day away on the same control, so the walk is one post per day.
  const jump = async () => {
    if (!html) return;
    const target = todayNumber();
    for (let count = 0; count < MAX_JUMP; count += 1) {
      const date = boardDate(html);
      if (!date || boardNumber(date) === target) break;
      html = await move(boardNumber(date) < target ? "next" : "back");
    }
    paint(html);
    stampNow();
  };

  let running = false;
  const guard = async (work) => {
    if (running) return;
    running = true;
    for (const button of [refresh, back, next, today]) button.disabled = true;
    try {
      await work();
    } catch (error) {
      fail(error);
    }
    running = false;
    refresh.disabled = false;
    back.disabled = false;
    next.disabled = false;
    const date = boardDate(html);
    today.disabled = !date || boardNumber(date) === todayNumber();
  };

  refresh.addEventListener("click", () => guard(load));
  back.addEventListener("click", () => guard(() => step("back")));
  next.addEventListener("click", () => guard(() => step("next")));
  today.addEventListener("click", () => guard(jump));
  guard(load);
  setInterval(() => {
    if (!panel.hidden && !document.hidden) guard(load);
  }, REFRESH_MS);
}
return { scoreCell, gameState, todayBoard, boardDate, boardNumber, todayNumber, renderToday };
})();

// ---- src/bbm-mine.js
const { mineIDs } = (() => {
// The home feed marks the stories about the user's own players. Basketball
// Monster marks nothing client-side — no class and no data attribute says a
// story is yours — so the id set is read from the two pages that hold it: the
// selected box of the watch list, and the roster of the user's own team. Both
// are fetched once and cached, and a page that will not load leaves the feed
// unmarked rather than failing it.
const KEY = "cgmBbmMine";
const TTL = 6 * 60 * 60 * 1000;
const PAGES = ["watchlist.aspx", "teamplayers.aspx"];

const read = () => { try { return JSON.parse(localStorage.getItem(KEY)) || null; } catch { return null; } };
const write = (ids) => { try { localStorage.setItem(KEY, JSON.stringify({ at: Date.now(), ids })); } catch { /* storage blocked */ } };

// The watch list prints its players one option each, with the player id as the
// option value.
const watchIDs = (doc) => [...doc.querySelectorAll("#SelectedPlayersListBox option")]
  .map((option) => option.value.trim())
  .filter(Boolean);

// A name with its spacing and punctuation gone, so "Karl-Anthony Towns" and
// "Karl Anthony Towns" are the same key.
const nameKey = (name) => String(name || "").toLowerCase().replace(/[^a-z0-9]/g, "");

const nameIDs = (doc) => {
  const raw = doc.querySelector('script[id*="pageTitleRowSearch"]')?.textContent || "";
  try {
    return new Map(JSON.parse(raw).map((entry) => [nameKey(entry.name), String(entry.id)]));
  } catch { return new Map(); }
};

// The roster table is the one that carries an ownership column.
const rosterTable = (doc) => [...doc.querySelectorAll("table")]
  .find((table) => /own%/i.test(table.rows[0]?.textContent || "")) || null;

// Roster rows print the player name as plain text, so each row is matched
// against the page's own id index by name.
const rosterIDs = (doc) => {
  const byName = nameIDs(doc);
  const rows = rosterTable(doc)?.tBodies[0]?.rows || [];
  return [...rows]
    .map((row) => [...row.cells].map((cell) => byName.get(nameKey(cell.textContent))).find(Boolean))
    .filter(Boolean);
};

async function mineIDs() {
  const cached = read();
  if (cached && Date.now() - cached.at < TTL) return new Set(cached.ids);

  const ids = new Set();
  for (const page of PAGES) {
    // The pages are only readable from the site's own origin; anywhere else
    // (a saved copy, a test host) there is nothing to read and nothing to say.
    if (new URL(page, location.href).origin !== location.origin) return ids;
    try {
      const response = await fetch(page, { credentials: "same-origin" });
      if (!response.ok) continue;
      const doc = new DOMParser().parseFromString(await response.text(), "text/html");
      (page.startsWith("watch") ? watchIDs(doc) : rosterIDs(doc)).forEach((id) => ids.add(id));
    } catch { /* the page is optional: without it the feed is simply unmarked */ }
  }
  // A run where both pages failed must not be remembered as "you own nobody".
  if (ids.size) write([...ids]);
  return ids;
}
return { mineIDs };
})();

// ---- src/bbm-home.js
const { elapsedBucket, dayBucket, wordLabel, buildBylines, commentBodies, tweetFromOEmbed, tweetEndpoints, buildNews, buildGames, buildHome } = (() => {
// The home page ships its widgets as a row of equal cards that each show
// everything at once. This rebuilds it as four tabs: Player News (a uniform
// run of compact stories under elapsed-time headings), NBA Today (the day's
// games with their live scores, read from the Box Scores page), User Comments
// (the full list, bodies borrowed from the comments page), and Matchup Monster
// (one live scoreboard card per league). Nodes are moved, never cloned, so the
// site's own postbacks keep working.






const slotOf = (col) => {
  const title = col.querySelector("h3")?.textContent.trim().toLowerCase() || "";
  if (title.includes("player news")) return "news";
  if (title.includes("user comments")) return "comments";
  return null;
};

const div = (className, ...nodes) => {
  const box = Object.assign(document.createElement("div"), { className });
  box.append(...nodes.filter(Boolean));
  return box;
};

// The site separates a heading from the widget under it with a non-breaking
// space. Once the heading moves into a head row that space would sit alone and
// draw a blank line, so a whitespace-only text node goes with the heading.
function dropStraySpace(host) {
  for (const node of [...host.childNodes]) {
    if (node.nodeType === 3 && !node.textContent.trim()) node.remove();
  }
}

// Every card reads the same: no lead, so the first stories show instead of
// one story dwarfing the rest. The list shows the newest few until asked.
const NEWS_VISIBLE = 4;
const COMMENTS_VISIBLE = 4;

// How long ago a story happened, from the site's own relative stamp. The
// headings are elapsed time rather than calendar days, because a story carries
// only its relative age.
const HOURS = { s: 1 / 3600, m: 1 / 60, h: 1, d: 24, w: 24 * 7 };
function elapsedBucket(since) {
  const match = /^([\d.]+)\s*(s|m|h|d|w)/.exec(String(since || "").trim());
  if (!match) return "Earlier";
  const hours = Number(match[1]) * HOURS[match[2]];
  if (hours < 1) return "Last hour";
  if (hours < 24) return "Today";
  if (hours < 48) return "Yesterday";
  if (hours < 24 * 7) return "This week";
  return "Earlier";
}

// A feed that carries several days needs day-level headings: the home page's
// coarse ones fold everything from two days to a week into one bucket. The
// site's own stamps can read "more than" an age, so that mark is ignored.
function dayBucket(since) {
  const match = /^>?\s*([\d.]+)\s*(s|m|h|d|w)/.exec(String(since || "").trim());
  if (!match) return "Earlier";
  const value = Number(match[1]);
  const unit = match[2];
  if (unit === "s" || unit === "m") return "Last hour";
  if (unit === "h") return value < 24 ? "Today" : "Yesterday";
  if (unit === "w") return "Earlier";
  if (value < 1) return "Today";
  if (value < 2) return "Yesterday";
  return `${Math.floor(value)} days ago`;
}

// The site's status words arrive in capitals; a chip reads better in sentence
// case.
function wordLabel(word) {
  return String(word || "").toLowerCase().replace(/\b[a-z]/g, (letter) => letter.toUpperCase());
}

const storyCards = (body) => [...body.querySelectorAll(".news-card")].filter((card) => card.querySelector(".news-card-test-header"));

// Tag every card with its status word and its elapsed bucket, and let a click
// open the full note in place.
function tagStories(cards, bucket = elapsedBucket) {
  const words = new Map();
  for (const card of cards) {
    card.classList.add("cgm-story");
    const word = card.querySelector(".news-card-test-status-corner")?.textContent.trim() || "";
    card.dataset.cgmWord = word;
    card.dataset.cgmBucket = bucket(card.querySelector(".time-since")?.textContent);
    words.set(word, (words.get(word) || 0) + 1);
    // The priority word becomes a coloured dot, so it keeps its word as a tooltip.
    const level = card.querySelector(".news-card-test-level");
    if (level) level.title = level.textContent.trim();
    // The status pill and the story's own meta ride on the name's line: the
    // pill after the name, the source link and the age at the far end of it.
    // The site floats the meta over the card's corner, and the row it left
    // behind was a band of air above every name.
    const name = card.querySelector(".display-player-name");
    const pill = card.querySelector(".news-card-test-corner-group");
    if (name && pill && !pill.dataset.cgmMoved) {
      pill.dataset.cgmMoved = "1";
      name.after(pill);
    }
    const player = card.querySelector(".display-player");
    const header = card.querySelector(".news-card-test-header");
    if (player && header && !header.dataset.cgmMoved) {
      header.dataset.cgmMoved = "1";
      player.append(header);
    }
    card.addEventListener("click", (event) => {
      if (!event.target.closest("a, button, input, label, select")) card.classList.toggle("cgm-open");
    });
  }
  return words;
}

// The card opens with a byline row: headshot plus team logo, RotoWire-style.
// Runs after the headshots land, so the images exist to move; skipped cards
// keep the old row and still read fine. A player with no team has no logo to
// move, but the headshot still belongs in the left rail: without a byline the
// card keeps an empty first column and the picture stays beside the name.
function buildBylines(root = document) {
  for (const card of root.querySelectorAll(".cgm-story:not(:has(.cgm-byline))")) {
    const head = card.querySelector(".cgm-id > .cgm-head");
    if (!head) continue;
    const logo = card.querySelector(".display-player-team > img");
    const byline = div("cgm-byline");
    byline.append(head, ...(logo ? [logo] : []));
    card.prepend(byline);
  }
}

// The home page ships comment cards without bodies; the full comments page
// renders them keyed by the same reply id, so the home page borrows the text
// for its own cards. Pure string work (each body pairs with the reply id that
// follows it in the same card) so tests can cover it without a DOM.
function commentBodies(html) {
  const page = String(html);
  const texts = [...page.matchAll(/<div class="comment-card-text"[^>]*>([\s\S]*?)<\/div>/g)];
  const ids = [...page.matchAll(/[\s"]data-cc-reply="(\d+)"/g)];
  const bodies = new Map();
  texts.forEach((text, at) => {
    const end = texts[at + 1]?.index ?? Infinity;
    const id = ids.find((match) => match.index > text.index && match.index < end);
    if (id && text[1].trim()) bodies.set(id[1], text[1]);
  });
  return bodies;
}

const COMMENT_BODIES_KEY = "cgmBbmCommentBodies";
const COMMENT_BODIES_TTL = 10 * 60 * 1000;

// Fill the home comment cards from the full comments page, once per tab per
// ten minutes. A card with no match keeps its teaser row, and a page that
// will not load leaves every teaser standing rather than failing the page.
async function fillComments(scope) {
  const cards = [...scope.querySelectorAll(".comment-card")];
  if (!cards.length) return;
  try {
    let cached = null;
    try { cached = JSON.parse(sessionStorage.getItem(COMMENT_BODIES_KEY)); } catch { /* storage blocked */ }
    let bodies = cached && Date.now() - cached.at < COMMENT_BODIES_TTL ? new Map(Object.entries(cached.bodies)) : null;
    if (!bodies) {
      // The comments page is only readable from the site's own origin; anywhere
      // else (a saved copy, a test host) there is nothing to read and nothing
      // to say.
      if (new URL("usercomments.aspx", location.href).origin !== location.origin) return;
      const response = await fetch("usercomments.aspx", { credentials: "same-origin" });
      if (!response.ok) return;
      bodies = commentBodies(await response.text());
      try { sessionStorage.setItem(COMMENT_BODIES_KEY, JSON.stringify({ at: Date.now(), bodies: Object.fromEntries(bodies) })); } catch { /* storage blocked */ }
    }
    if (!bodies.size) return;
    for (const card of cards) {
      const id = card.querySelector("[data-cc-reply]")?.getAttribute("data-cc-reply");
      const text = card.querySelector(".comment-card-text");
      const body = id && bodies.get(id);
      if (!text || !body) continue;
      text.innerHTML = body;
      card.classList.remove("cgm-empty");
    }
  } catch { /* the teasers stand; a failed fill is not a page error */ }
}
// The tweet behind a story's source link, read through the oEmbed endpoint
// (X blocks direct reads, so a CORS proxy carries it). Pure string work so
// tests can cover it without a DOM.
function tweetFromOEmbed(json) {
  let data = null;
  try { data = typeof json === "string" ? JSON.parse(json) : json; } catch { return null; }
  const p = data && typeof data.html === "string" && data.html.match(/<p[^>]*>([\s\S]*?)<\/p>/);
  if (!p) return null;
  const text = p[1]
    .replace(/<br\s*\/?>/gi, " ")
    .replace(/<[^>]+>/g, "")
    .replace(/&(amp|lt|gt|quot|#39|#x27);/g, (m) => ({ "&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&#39;": "'", "&#x27;": "'" }[m] || m))
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return null;
  const author = data.author_name || "";
  const handle = String(data.author_url || "").split("/").filter(Boolean).pop() || "";
  return { author, handle, text };
}

const TWEET_KEY = "cgmBbmTweets";
const TWEET_TTL = 60 * 60 * 1000;

// oEmbed answers 200 without CORS headers and the bundle runs under page
// CORS, so the fetch goes through a small ordered chain: the userscript
// manager's own request API when granted (no CORS involved), then plain fetch
// first in case CORS ever opens, then public CORS proxies. Pure list so tests
// can cover the order without a DOM.
function tweetEndpoints(href) {
  const oembed = `https://publish.x.com/oembed?url=${encodeURIComponent(href)}&omit_script=true`;
  return [
    { kind: "direct", url: oembed },
    { kind: "allorigins", url: "https://api.allorigins.win/get?url=" + encodeURIComponent(oembed) },
    { kind: "raw", url: "https://api.allorigins.win/raw?url=" + encodeURIComponent(oembed) },
    { kind: "codetabs", url: "https://api.codetabs.com/v1/proxy?quest=" + encodeURIComponent(oembed) },
  ];
}

// The classic userscript request API bypasses page CORS entirely; it exists
// only when the manager grants it, so every other context falls through.
function gmFetchText(url) {
  return new Promise((resolve, reject) => {
    try {
      GM_xmlhttpRequest({
        method: "GET", url, timeout: 20000,
        onload: (r) => (r.status >= 200 && r.status < 300 ? resolve(r.responseText) : reject(new Error(`oEmbed ${r.status}`))),
        onerror: () => reject(new Error("oEmbed request failed")),
        ontimeout: () => reject(new Error("oEmbed timed out")),
      });
    } catch (e) { reject(e); }
  });
}

const withTimeout = (promise, ms) => Promise.race([
  promise,
  new Promise((_, reject) => setTimeout(() => reject(new Error("oEmbed timed out")), ms)),
]);

async function fetchTweetJson(href) {
  const endpoints = tweetEndpoints(href);
  if (typeof GM_xmlhttpRequest === "function") {
    try {
      const tweet = tweetFromOEmbed(await withTimeout(gmFetchText(endpoints[0].url), 25000));
      if (tweet) return tweet;
    } catch { /* fall through to the fetch chain */ }
  }
  for (const { kind, url } of endpoints) {
    try {
      const response = await withTimeout(fetch(url), 25000);
      if (!response.ok) continue;
      const body = kind === "direct" || kind === "raw" ? await response.text() : (await response.json()).contents;
      const tweet = tweetFromOEmbed(body);
      if (tweet) return tweet;
    } catch { /* next endpoint */ }
  }
  return null;
}

// A story that links a tweet shows the tweet under the note. Only shown cards
// fetch, each URL once per page load, and a failed fetch keeps the source
// link standing instead of failing the page.
async function loadTweetEntry(href, cache) {
  const fresh = (at) => Date.now() - at < TWEET_TTL;
  let entry = cache[href];
  if (!entry || !fresh(entry.at)) {
    const tweet = await fetchTweetJson(href);
    if (!tweet) return null;
    entry = { ...tweet, at: Date.now() };
    cache[href] = entry;
    try { sessionStorage.setItem(TWEET_KEY, JSON.stringify(cache)); } catch { /* storage blocked */ }
  }
  return entry;
}

function renderTweetBox(card, entry) {
  const box = div("cgm-tweet", div("cgm-tweet-via", `Via ${entry.author}${entry.handle ? ` (@${entry.handle})` : ""}`));
  box.append(entry.text);
  const row = card.querySelector(".news-card-test-body-row");
  if (row) row.after(box);
  else card.append(box);
}

async function fillTweets(cards) {
  const jobs = cards.filter((card) => {
    if (card.dataset.cgmTweet) return false;
    card.dataset.cgmTweet = "1";
    const href = card.querySelector(".news-card-test-source")?.getAttribute("href") || "";
    return /(twitter\.com|x\.com)\/\w+\/status\/\d+/.test(href);
  });
  if (!jobs.length) return;
  let cache = {};
  try { cache = JSON.parse(sessionStorage.getItem(TWEET_KEY)) || {}; } catch { /* storage blocked */ }
  const one = async (card) => {
    const href = card.querySelector(".news-card-test-source")?.getAttribute("href") || "";
    try {
      const entry = await loadTweetEntry(href, cache);
      if (!entry) return;
      renderTweetBox(card, entry);
    } catch { /* the source link stands; a failed tweet is not a page error */ }
  };
  await Promise.allSettled(jobs.map(one));
}

// The filter row: one chip per status word with its count, plus All.
function storyChips(cards, words, onPick) {
  const chips = div("cgm-chips");
  const chip = (key, label) => {
    const button = Object.assign(document.createElement("button"), { type: "button", className: "cgm-chip", textContent: label });
    button.setAttribute("aria-pressed", String(key === "all"));
    button.addEventListener("click", () => {
      onPick(key);
      for (const other of chips.children) other.setAttribute("aria-pressed", String(other === button));
    });
    return button;
  };
  chips.append(chip("all", `All ${cards.length}`));
  for (const [word, count] of words) chips.append(chip(word, `${wordLabel(word) || "No status"} ${count}`));
  return chips;
}

// What the active filter shows: the newest few, uniform, until "Show all".
function storyParts(shown, all) {
  const listed = all ? shown : shown.slice(0, NEWS_VISIBLE);
  return { listed: new Set(listed) };
}

// A heading sits above the first brief of each elapsed bucket.
function paintHeadings(list, cards) {
  for (const old of [...list.querySelectorAll(".cgm-dayhead")]) old.remove();
  let bucket = null;
  for (const card of cards) {
    if (card.dataset.cgmBucket === bucket) continue;
    bucket = card.dataset.cgmBucket;
    card.before(div("cgm-dayhead", bucket));
  }
}

// The player a story is about, by the id the site links them by.
const playerID = (card) => /[?&]i=(\d+)/.exec(card.querySelector(".display-player-name")?.getAttribute("href") || "")?.[1] || null;

function paint(cards, list, ui, state, fold = true, mine = false) {
  const shown = cards.filter((card) => {
    if (state.word !== "all" && card.dataset.cgmWord !== state.word) return false;
    // "My Players" keeps only the stories about the reader's own players.
    if (mine && state.mine && !state.mineIds.has(playerID(card))) return false;
    return true;
  });
  const { listed } = fold ? storyParts(shown, state.all) : { listed: new Set(shown) };
  // The feed is one uniform run until "Show all"; any other story is out of
  // the list, not merely unstyled.
  for (const card of cards) {
    card.classList.toggle("cgm-gone", !listed.has(card));
    card.classList.remove("cgm-lead", "cgm-brief");
  }
  paintHeadings(list, shown.filter((card) => listed.has(card)));
  ui.empty.hidden = shown.length > 0;
  ui.more.hidden = !fold || shown.length <= NEWS_VISIBLE;
  ui.more.textContent = state.all ? "Show fewer" : `Show all ${shown.length} stories`;
}

// Stories about the user's own players take a mark once the id set arrives.
function markMine(cards) {
  const badge = Object.assign(document.createElement("span"), { className: "cgm-mine-mark", textContent: "Your player" });
  badge.title = "This story is about a player on your team or watch list";
  mineIDs().then((ids) => {
    if (!ids.size) return;
    for (const card of cards) {
      const id = /[?&]i=(\d+)/.exec(card.querySelector(".display-player-name")?.getAttribute("href") || "")?.[1];
      if (!id || !ids.has(id)) continue;
      card.classList.add("cgm-mine");
      card.querySelector(".news-card-test-header")?.append(badge.cloneNode(true));
    }
  });
}

// The feed. `all` keeps every story on the page instead of folding them
// behind "Show all"; `bucket` decides the headings; `mine` turns the site's
// own "My Players" control into a filter of the feed instead of a postback
// that would replace the feed with the site's own news.
function buildNews(body, { all = false, bucket = elapsedBucket, mine = false } = {}) {
  let cards = storyCards(body);
  if (!cards.length) return null;
  let words = tagStories(cards, bucket);

  // The site's own heading — the link to the full feed — stays, and moves in
  // beside the status chips.
  const head = div("cgm-panelhead");
  const left = div("cgm-panelhead-left");
  const heading = body.querySelector("h3");
  if (heading) {
    const wrapper = heading.parentElement;
    left.append(heading);
    if (wrapper && wrapper !== body && !wrapper.children.length) wrapper.remove();
  }

  const state = { word: "all", all: false, mine: false, mineIds: new Set() };
  const list = div("cgm-stories");
  list.append(...cards);
  const empty = Object.assign(document.createElement("p"), { className: "cgm-newsempty", textContent: "No stories" });
  empty.hidden = true;
  const more = Object.assign(document.createElement("button"), { type: "button", className: "cgm-show-all" });
  const ui = { empty, more };
  const draw = () => {
    paint(cards, list, ui, state, !all, mine);
    fillTweets(cards.filter((card) => !card.classList.contains("cgm-gone")));
  };
  more.addEventListener("click", () => { state.all = !state.all; draw(); });

  const bar = div("cgm-newsbar");
  const mineBox = Object.assign(document.createElement("span"), { className: "cgm-mine" });
  mineBox.append(...[body.querySelector("#MYONLY"), body.querySelector('label[for="MYONLY"]')].filter(Boolean));
  const setWords = (next) => {
    words = next;
    bar.replaceChildren(storyChips(cards, words, (key) => { state.word = key; state.all = false; draw(); }), mineBox);
  };
  setWords(words);
  left.append(bar);
  head.append(left);
  dropStraySpace(body);

  // Whatever the heading and the cards left behind would only be an empty box.
  for (const spare of [...body.querySelectorAll("div")]) {
    if (!spare.children.length && !spare.textContent.trim()) spare.remove();
  }

  body.prepend(head);
  body.append(list, empty, more);
  draw();

  if (mine) {
    const check = mineBox.querySelector("input");
    if (check) {
      // The site's control posts the page back, which would bring the site's
      // own news in place of this feed, so it filters here instead.
      check.removeAttribute("onclick");
      check.addEventListener("change", () => { state.mine = check.checked; draw(); });
      mineIDs().then((ids) => { state.mineIds = ids; draw(); });
    }
  }

  markMine(cards);

  // A page that carries more history swaps the cards and keeps the feed. The
  // cards arrive after the page's own images and bylines have run, so they are
  // given their headshots and their byline here.
  return {
    setCards(next) {
      for (const card of cards) card.remove();
      cards = next;
      state.word = "all";
      list.replaceChildren(...cards);
      setWords(tagStories(cards, bucket));
      draw();
      enhanceAll(list);
      buildBylines(list);
      markMine(cards);
    },
  };
}

// The games widget is a flat run of divs: time, matchup, then player rows.
function buildGames(box) {
  const groups = [];
  const notes = [];
  const attach = (el) => {
    if (el.matches('[class*="daily-status-updates-game"]')) return groups.push({ time: el, teams: null, players: [] });
    const last = groups.at(-1);
    if (!last) return;
    if (el.classList.contains("daily-status-updates-teams")) last.teams = el;
    else if (el.querySelector("a")) last.players.push(el);
    else notes.push(el); // the "no player status" legend
  };
  for (const el of [...box.children]) attach(el);

  for (const { time, teams, players } of groups) {
    const details = document.createElement("details");
    details.className = "cgm-game";
    const summary = document.createElement("summary");
    summary.append(...[teams, time].filter(Boolean));
    if (players.length) summary.append(Object.assign(document.createElement("span"), { className: "cgm-count", textContent: String(players.length) }));
    details.append(summary, ...players);
    box.append(details);
  }
  notes.forEach((note) => box.append(note));

  // The day steps move down beside the "Undetermined Only" box, so the header
  // holds the day and its date alone.
  const steps = box.firstElementChild?.querySelector("small.float-right");
  const toggle = box.querySelector("#HIDEINOUT")?.closest("div");
  if (steps && toggle) toggle.prepend(steps);
}

const widget = (col) => col?.querySelector(".card-based, .daily-status-updates") || col;

// Walk the page's own columns and take each widget out of its Bootstrap column.
function sections(row) {
  const found = {};
  for (const col of [...row.children]) {
    const slot = slotOf(col);
    if (slot) found[slot] = widget(col);
  }
  return { found };
}

// A section head row: the site's own heading, which keeps its link, plus an
// optional control from the same widget.
function headRow(card, extra) {
  const row = div("cgm-panelhead");
  const heading = card?.querySelector("h3");
  if (heading) {
    const wrapper = heading.parentElement;
    row.append(heading);
    if (wrapper && wrapper !== card && !wrapper.children.length) wrapper.remove();
  }
  row.append(...[extra].filter(Boolean));
  card?.prepend(row);
  if (card) dropStraySpace(card);
}

const TAB_KEY = "cgmBbmTab";
const readTab = () => {
  try { return localStorage.getItem(TAB_KEY) || "news"; } catch { return "news"; }
};
const writeTab = (tab) => {
  try { localStorage.setItem(TAB_KEY, tab); } catch { /* storage blocked */ }
};

function buildHome() {
  const row = document.querySelector(".container-fluid > .row");
  if (!row || document.querySelector(".cgm-home")) return;
  const { found } = sections(row);
  if (!found.news) return; // not the layout this was written for; leave the page alone

  // The schedule widget leaves the home page. The NBA Today tab carries the
  // day's games with their live scores instead.
  const gamesCol = document.querySelector(".daily-status-updates")?.closest('[class*="col"]');
  if (gamesCol) gamesCol.remove();

  const newsPanel = div("cgm-panel cgm-news", found.news);
  const todayPanel = div("cgm-panel cgm-today");
  const commentsPanel = div("cgm-panel cgm-comments", found.comments);
  const livePanel = div("cgm-panel cgm-live");
  const panels = { news: newsPanel, today: todayPanel, comments: commentsPanel, live: livePanel };
  let todayStarted = false;
  let liveStarted = false;
  const ensureToday = () => {
    if (!todayStarted) {
      todayStarted = true;
      renderToday(todayPanel);
    }
  };
  const ensureLive = () => {
    if (!liveStarted) {
      liveStarted = true;
      renderLive(livePanel);
    }
  };
  const pick = (tab) => {
    for (const [key, panel] of Object.entries(panels)) panel.hidden = key !== tab;
    writeTab(tab);
    if (tab === "today") ensureToday();
    if (tab === "live") ensureLive();
  };
  const tabs = div(
    "cgm-tabs",
    segmented(
      [
        { key: "news", label: "Player News" },
        { key: "today", label: "NBA Today" },
        { key: "comments", label: "User Comments" },
        { key: "live", label: "Matchup Monster" },
      ],
      pick,
      readTab(),
    ),
  );
  const home = div("cgm-home", tabs, newsPanel, todayPanel, commentsPanel, livePanel);

  row.before(home);
  row.remove();

  buildNews(found.news);
  // The tab's own heading points at the site's All Player News page, which the
  // redesign does not own; the news page carries the week, so that is where
  // the reader goes.
  const heading = found.news.querySelector(".cgm-panelhead a");
  if (heading) heading.href = "playernews.aspx";
  headRow(found.comments, found.comments?.querySelector(".bm-custom-select"));
  if (found.comments) {
    for (const card of found.comments.querySelectorAll(".comment-card")) {
      card.classList.toggle("cgm-empty", !card.querySelector(".comment-card-text")?.textContent.trim());
    }
    limit([...found.comments.querySelectorAll(".comment-card")], COMMENTS_VISIBLE, found.comments, "comments");
    fillComments(found.comments);
  }

  pick(readTab());
}
return { elapsedBucket, dayBucket, wordLabel, buildBylines, commentBodies, tweetFromOEmbed, tweetEndpoints, buildNews, buildGames, buildHome };
})();

// ---- src/bbm-news.js
const { buildNewsPage } = (() => {
// The Player News page becomes one wide feed of the site's own news, with
// several days of it, and nothing else on the page. The stories come from the
// site's All Player News page, whose "Past Days" control decides how much
// history it carries; the cards move into this page, so their links keep
// working. The page's comments, polls, games and returning-player panels go.



const UPDATES_URL = "statusupdates.aspx";
const DEFAULT_DAYS = 7;
const DAYS = [1, 2, 3, 4, 5, 6, 7];

const div = (className, ...nodes) => {
  const box = Object.assign(document.createElement("div"), { className });
  box.append(...nodes.filter(Boolean));
  return box;
};

// The site's own cards, read out of the page it sends. A template holds them
// until they are moved, so the fetched page's own ids never reach this one.
function cardNodes(html) {
  const template = document.createElement("template");
  template.innerHTML = html;
  return [...template.content.querySelectorAll(".news-card")];
}

// The number of days the site answered with. The control keeps it in the
// session, so a post the site ignores answers with the days it already had.
function daysIn(html) {
  const select = String(html).match(/<select name='DAYSDD'[^>]*>([\s\S]*?)<\/select>/);
  const selected = select && select[1].match(/<option[^>]*selected[^>]*value='(\d+)'/);
  return selected ? Number(selected[1]) : null;
}

// The history the site's "Past Days" control asks for. The control is a
// postback, so the page is posted with the number of days it should carry.
async function loadUpdates(days) {
  const first = await (await fetch(pageURL(UPDATES_URL), { credentials: "same-origin" })).text();
  const ask = (fields) => postFields(pageURL(UPDATES_URL), fields, {
    DAYSDD: String(days),
    __EVENTTARGET: "DAYSDD",
    __EVENTARGUMENT: "",
  });
  let posted = await ask(hiddenFields(first));
  // A post the site ignored would answer with the days it already had, so the
  // question is asked again with the viewstate that answer carries.
  if (daysIn(posted) !== days) posted = await ask(hiddenFields(posted));
  return { cards: cardNodes(posted), days: daysIn(posted) };
}

// The page keeps the news and nothing else. The panels that go are removed
// with their column, so the news takes the whole width. The site's own hidden
// refresh timer sits inside the news column, so it is removed on its own.
function clearPage() {
  for (const name of ["CommentsUpdatePanel", "PollsUpdatePanel", "GamesUpdatePanel"]) {
    const node = document.getElementById(`ContentPlaceHolder1_${name}`);
    (node?.closest("[class*='col']") || node)?.remove();
  }
  document.getElementById("ContentPlaceHolder1_MainTimer")?.remove();
}

function buildNewsPage() {
  const panel = document.querySelector("#ContentPlaceHolder1_NewsPanel");
  if (!panel) return;
  clearPage();

  const widget = panel.querySelector(".card-based") || panel;
  const column = widget.closest("[class*='col']");
  const row = column?.closest(".row");
  const feed = div("cgm-feed cgm-news");
  const host = row || column;
  if (host) {
    host.before(feed);
    feed.append(widget);
    host.remove();
  } else {
    feed.append(widget);
  }

  // The days the reader asks for, beside the status chips.
  const days = div("cgm-feed-days");
  const select = Object.assign(document.createElement("select"), { className: "cgm-days" });
  for (const day of DAYS) {
    const option = Object.assign(document.createElement("option"), { value: String(day), textContent: day === 1 ? "Today" : `${day} days` });
    if (day === DEFAULT_DAYS) option.selected = true;
    select.append(option);
  }
  days.append(Object.assign(document.createElement("span"), { className: "cgm-days-label", textContent: "Past" }), select);

  // The site's own cards are today's news only, so the history replaces them
  // once it arrives. The feed is built first, on the page's own cards, so the
  // history can be swapped into it.
  const controller = buildNews(widget, { all: true, bucket: dayBucket, mine: true });
  if (!controller) return;

  // The days control sits beside the chips, in the head row's right group.
  widget.querySelector(".cgm-panelhead")?.append(days);
  select.addEventListener("change", async () => {
    select.disabled = true;
    try {
      const history = await loadUpdates(Number(select.value));
      // The control shows the days the site actually answered with, so it
      // never claims a history the page does not carry.
      if (history.days) select.value = String(history.days);
      controller.setCards(history.cards);
    } catch (error) {
      console.error("ClutchGM could not read the news history", error);
    }
    select.disabled = false;
  });

  loadUpdates(DEFAULT_DAYS).then(
    (history) => {
      if (history.days) select.value = String(history.days);
      controller.setCards(history.cards);
    },
    (error) => {
      console.error("ClutchGM could not read the news history", error);
    },
  );
}
return { buildNewsPage };
})();

// ---- src/bbm-legibility.js
const { fixLegibility } = (() => {
// The site colours some text for the opposite theme (white on a pale row, dark
// orange on a dark header). Where text is demonstrably under 4.5:1 against its
// real backdrop, move that one element's colour toward black or white until it
// reads. Nothing else is touched, so correct styling is never overridden.


const SKIP = /^(SCRIPT|STYLE|OPTION|SVG|PATH|I|INPUT|SELECT|TEXTAREA)$/;
const ownText = (el) => [...el.childNodes].some((node) => node.nodeType === 3 && node.textContent.trim());

// Chrome serialises color-mix() as color(srgb r g b), so accept both forms.
function toRgb(value) {
  const srgb = String(value).match(/^color\(srgb ([\d.]+) ([\d.]+) ([\d.]+)(?: \/ ([\d.]+))?\)/);
  if (srgb) return { rgb: [srgb[1], srgb[2], srgb[3]].map((n) => Math.round(+n * 255)), alpha: srgb[4] === undefined ? 1 : +srgb[4] };
  const rgb = parseColor(value);
  const alpha = String(value).match(/rgba\([^)]*,\s*([\d.]+)\)/);
  return rgb ? { rgb, alpha: alpha ? +alpha[1] : 1 } : null;
}

function backdrop(el) {
  const chain = [];
  for (let node = el; node; node = node.parentElement) chain.push(node);
  let color = [255, 255, 255];
  for (const node of chain.reverse()) {
    const layer = toRgb(getComputedStyle(node).backgroundColor);
    if (layer && layer.alpha > 0) color = color.map((c, i) => c * (1 - layer.alpha) + layer.rgb[i] * layer.alpha);
  }
  return color.map(Math.round);
}

function fixLegibility() {
  const visible = (el) => { const rect = el.getBoundingClientRect(); return rect.width > 1 && rect.height > 1; };
  const jobs = [];
  for (const el of document.body.querySelectorAll("*")) {
    if (SKIP.test(el.tagName.toUpperCase()) || !ownText(el) || el.closest("svg, .bm-tooltip-content, [hidden], [data-cgm-chip]")) continue;
    const style = getComputedStyle(el);
    if (style.visibility === "hidden" || style.display === "none" || !visible(el)) continue;
    // Tag chips paint with -webkit-text-fill-color, which wins over color.
    const fill = style.webkitTextFillColor !== style.color;
    const text = toRgb(fill ? style.webkitTextFillColor : style.color);
    if (!text) continue;
    jobs.push({ el, text: text.rgb, alpha: text.alpha, fill });
  }
  // Read everything first, write second, so one fix cannot change another's backdrop mid-pass.
  const fixes = [];
  for (const { el, text, alpha, fill } of jobs) {
    const back = backdrop(el);
    const effective = text.map((c, i) => Math.round(c * alpha + back[i] * (1 - alpha)));
    const fixed = ensureTextContrast(effective, back);
    if (fixed.some((value, index) => value !== effective[index])) fixes.push([el, toCss(fixed), fill]);
  }
  window.__cgmLegibility = `${jobs.length} checked, ${fixes.length} fixed`;
  for (const [el, color, fill] of fixes) el.style.setProperty(fill ? "-webkit-text-fill-color" : "color", color, "important");
}
return { fixLegibility };
})();

// ---- src/bbm-player.js
const { buildPlayer } = (() => {
// Playerinfo hero and tooling. The badge strip becomes one card: a big
// headshot, the name with status and positions, and the facts as a two-sided
// table on the right. The page actions and view toggles move into one toolbox
// section, the schedule strip becomes day cards, and the stat toggles become
// grouped chips. Nodes move, never clones, so postbacks keep working.


const text = (node) => node?.textContent?.trim() ?? "";

// "Amen Thompson - HOU - PG SG": the name is the first text run, the team
// sits between dashes, positions are the colored spans.
function parseHeading(h1) {
  const raw = h1.firstChild?.nodeType === 3 ? h1.firstChild.textContent : h1.textContent;
  const name = raw.split(" - ")[0].trim() || text(h1).split(" - ")[0].trim() || text(h1);
  const team = (raw.match(/-\s*([A-Z]{2,3})\s*-/) || [])[1] || "";
  const positions = [...h1.querySelectorAll("span")].map((span) => text(span)).filter(Boolean);
  return { name, team, positions };
}

const STATUS_TINT = [
  [/probable/i, "#16a34a"],
  [/questionable/i, "#d97706"],
  [/doubtful/i, "#ea580c"],
  [/\bout\b/i, "#dc2626"],
];

// Badge items wrap their links in value spans that sometimes survive empty
// once the link moves out. Only nodes with text or a control survive.
function keepNode(node) {
  if (text(node)) return true;
  if (node.querySelector?.("img,input,a,select,button,canvas,svg")) return true;
  return /^(IMG|INPUT|A|SELECT|BUTTON|CANVAS|SVG)$/i.test(node.tagName || "");
}

function statusPill(value) {
  const pill = document.createElement("span");
  pill.className = "cgm-hero-status";
  pill.textContent = value;
  const tint = STATUS_TINT.find(([pattern]) => pattern.test(value));
  pill.style.backgroundColor = tint ? tint[1] : "#64748b";
  return pill;
}

// The depth link may sit bare in the item or wrapped in a value span. Only a
// badge item holding nothing but that link folds into the team word; anything
// else stays a regular action.

// Badge text sometimes repeats itself across sibling nodes ("ankleankle").
// Drop any chunk already contained in another chunk and join the rest.
function dedupeChunks(chunks) {
  const unique = [...new Set(chunks)];
  return unique.filter((chunk) => !unique.some((other) => other !== chunk && other.includes(chunk)));
}

function depthAnchor(item, rest) {
  const anchor = rest.reduce((found, node) => found || (node.tagName === "A" ? node : node.querySelector?.("a") || null), null);
  if (!anchor || !/depth chart/i.test(text(anchor))) return null;
  if (text(item).trim() !== text(anchor).trim()) return null;
  return anchor;
}
function collectBadge(badge) {
  const pairs = [];
  const actions = [];
  let status = null;
  let depthHref = null;
  for (const item of [...badge.querySelectorAll(".player-stat-badge-item")]) {
    const label = text(item.querySelector(".player-stat-badge-label"));
    const rest = [...item.childNodes].filter((node) => !node.classList?.contains("player-stat-badge-label"));
    if (!label) {
      const depth = depthAnchor(item, rest);
      if (depth) {
        depthHref ||= depth.getAttribute("href");
        continue;
      }
      actions.push(...rest.filter(keepNode));
      continue;
    }
    if (/status/i.test(label) && !/questionable|games/i.test(label)) {
      status = dedupeChunks(rest.map(text).filter(Boolean)).join(" ") || text(item);
      continue;
    }
    if (/positions? played/i.test(label)) continue;
    pairs.push({ label, nodes: rest });
  }
  return { pairs, actions, status, depthHref };
}

function buildSub(team, positions, depthHref) {
  const sub = document.createElement("div");
  sub.className = "cgm-hero-sub";
  const logo = team ? teamLogo(team, "cgm-hero-logo") : null;
  if (logo) sub.append(logo);
  if (team) {
    const word = Object.assign(document.createElement(depthHref ? "a" : "span"), { className: "cgm-hero-team", textContent: team });
    if (depthHref) {
      word.href = depthHref;
      word.title = `${team} depth chart`;
    }
    sub.append(word);
  }
  for (const position of positions) {
    sub.append(Object.assign(document.createElement("span"), { className: "cgm-hero-pos", textContent: position }));
  }
  return sub.children.length ? sub : null;
}

function buildFacts(pairs) {
  const table = document.createElement("table");
  table.className = "cgm-hero-facts";
  const body = document.createElement("tbody");
  table.append(body);
  for (let at = 0; at < pairs.length; at += 2) {
    const row = document.createElement("tr");
    for (const pair of pairs.slice(at, at + 2)) {
      row.append(Object.assign(document.createElement("th"), { scope: "row", textContent: pair.label }));
      const value = document.createElement("td");
      value.append(...pair.nodes);
      row.append(value);
    }
    body.append(row);
  }
  return body.rows.length ? table : null;
}

// The page ships its Watch submit twice (page top and badge). The hero keeps
// one; the rest go when the toolbox places it.
function oneWatch(nodes) {
  let kept = false;
  return nodes.filter((node) => {
    if (node.name !== "ToggleWatchButton") return true;
    if (kept) {
      node.remove();
      return false;
    }
    kept = true;
    return true;
  });
}
function buildHero(h1, badge) {
  const { name, team, positions } = parseHeading(h1);
  const { pairs, actions, status, depthHref } = collectBadge(badge);
  const hero = document.createElement("section");
  hero.className = "cgm-hero";
  hero.setAttribute("aria-label", `${name} details`);

  const photo = document.createElement("div");
  photo.className = "cgm-hero-photo";
  photo.append(headshot(name, "cgm-hero-head") || document.createTextNode(""));
  hero.append(photo);

  const main = document.createElement("div");
  main.className = "cgm-hero-main";
  hero.append(main);

  h1.classList.add("cgm-hero-name");
  h1.textContent = name;
  const title = document.createElement("div");
  title.className = "cgm-hero-title";
  title.append(h1);
  if (status) title.append(statusPill(status));
  main.append(title);

  const sub = buildSub(team, positions, depthHref);
  if (sub) main.append(sub);

  const top = [...document.querySelectorAll('.container-fluid input[type="submit"]')]
    .find((input) => /watch/i.test(input.value || "") && !badge.contains(input));
  const mine = oneWatch(top && !actions.includes(top) ? [top, ...actions] : actions);
  let buttons = null;
  if (mine.length) {
    buttons = document.createElement("div");
    buttons.className = "cgm-hero-actions";
    buttons.append(...mine);
    main.append(buttons);
  }

  const facts = buildFacts(pairs);
  if (facts) hero.append(facts);
  return { hero, buttons };
}

// One toolbox card holds the section toggles as a single segmented tab bar.
// User comments start open; picking another tab closes the current one. The
// custom-comment toggle and its block go away entirely.

function syncPill(pill, toggle) {
  const target = document.querySelector(toggle.getAttribute("data-target"));
  pill.classList.toggle("cgm-on", !!target?.classList.contains("show"));
}

// Sections behave as tabs: one open at a time, so the open section gets the
// whole column. A pinned section stays open. Clicking a tab also scrolls to
// its section.
function closeOthers(current) {
  for (const toggle of [...document.querySelectorAll('.cgm-toolbox [data-toggle="collapse"]')]) {
    if (toggle === current) continue;
    if (toggle.closest(".cgm-section")?.querySelector('[aria-pressed="true"]')) continue;
    const target = document.querySelector(toggle.getAttribute("data-target"));
    if (!target || !target.classList.contains("show")) continue;
    target.classList.remove("show", "collapsing");
    target.style.height = "";
    toggle.setAttribute("aria-expanded", "false");
    toggle.closest(".cgm-section")?.classList.remove("cgm-on");
  }
}

function watchToggle(pill, toggle) {
  syncPill(pill, toggle);
  toggle.addEventListener("click", (event) => {
    const target = document.querySelector(toggle.getAttribute("data-target"));
    if (target && target.classList.contains("show")) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    closeOthers(toggle);
    if (target) setTimeout(() => target.scrollIntoView({ behavior: "smooth", block: "start" }), 120);
    setTimeout(() => syncPill(pill, toggle), 420);
  });
}

function moveToggles(chips) {
  const segments = document.createElement("div");
  segments.className = "cgm-segments";
  segments.setAttribute("role", "group");
  segments.setAttribute("aria-label", "Sections");
  for (const header of [...document.querySelectorAll(".collapse-control-header")]) {
    const toggle = header.querySelector('[data-toggle="collapse"]');
    const label = text(toggle);
    if (/custom comment/i.test(label)) {
      header.closest("div[id]")?.remove();
      const target = toggle?.getAttribute("data-target");
      if (target) document.querySelector(target)?.remove();
      continue;
    }
    if (!toggle) continue;
    const pill = document.createElement("span");
    pill.className = "cgm-section";
    pill.append(...header.childNodes);
    header.remove();
    watchToggle(pill, toggle);
    segments.append(pill);
  }
  if (segments.children.length) chips.append(segments);
}

// One tab starts open: user comments. The rest stay shut until picked.
function expandPinned(chips) {
  for (const toggle of [...chips.querySelectorAll('[data-toggle="collapse"]')]) {
    const target = document.querySelector(toggle.getAttribute("data-target"));
    if (!target || !/user comments/i.test(text(toggle))) continue;
    target.classList.add("show");
    toggle.setAttribute("aria-expanded", "true");
    toggle.closest(".cgm-section")?.classList.add("cgm-on");
  }
}

// The page ships the Watch submit twice; the hero keeps one and every other
// copy goes, wherever it sits. Dropping a duplicate can empty the value span
// that wrapped it, so those husks go too.
function dedupeWatch(buttons) {
  if (!buttons) return;
  const kept = buttons.querySelector('[name="ToggleWatchButton"]');
  if (!kept) return;
  for (const duplicate of [...document.querySelectorAll('[name="ToggleWatchButton"]')]) {
    if (duplicate !== kept) duplicate.remove();
  }
  for (const husk of [...buttons.querySelectorAll("span")]) {
    if (!text(husk) && !husk.querySelector("img,input,a,select,button,canvas,svg")) husk.remove();
  }
}

function buildToolbox() {
  const box = document.createElement("section");
  box.className = "cgm-toolbox";
  box.setAttribute("aria-label", "Player tools");

  const views = document.createElement("div");
  views.className = "cgm-tool-group";
  views.append(Object.assign(document.createElement("span"), { className: "cgm-tool-title", textContent: "Sections" }));
  const chips = document.createElement("div");
  chips.className = "cgm-tool-buttons";
  views.append(chips);
  moveToggles(chips);
  expandPinned(chips);
  if (chips.children.length) box.append(views);
  return box.children.length ? box : null;
}

// The schedule grid becomes a scrolling strip of day cards: date on top, the
// opponent as a home/away pill, off days dimmed. The table stays in the DOM.
function scheduleTable() {
  const days = /^(mon|tue|wed|thu|fri|sat|sun)$/i;
  return [...document.querySelectorAll("table.modern-stats-table")].find((table) => {
    const first = [...(table.querySelector("thead tr") || table.querySelector("tr"))?.children || []].map((cell) => cell.textContent.trim());
    return first.length > 7 && first.every((cell) => days.test(cell));
  });
}

function dayCard(dow, date, game) {
  const card = document.createElement("div");
  card.className = "cgm-day";
  card.append(Object.assign(document.createElement("span"), { className: "cgm-day-dow", textContent: dow }));
  card.append(Object.assign(document.createElement("span"), { className: "cgm-day-date", textContent: date }));
  const match = (game || "").trim();
  if (match) {
    const away = match.startsWith("@");
    const abbr = away ? match.slice(1) : match;
    const pill = document.createElement("span");
    pill.className = "cgm-day-game";
    if (away) pill.append("@");
    pill.append(abbr);
    card.append(pill);
    if (away) card.title = `at ${abbr}`;
    setTeamSkin(card, abbr);
  } else {
    card.classList.add("cgm-off");
  }
  return card;
}

// The day wears the opponent's colours: a light tint of the team's primary
// colour plus the full team logo as a backdrop under the day's own text.
function setTeamSkin(card, abbr) {
  const url = logoURL(abbr);
  if (url) card.style.setProperty("--cgm-team-logo", `url("${url}")`);
  const color = teamColor(abbr);
  if (color) card.style.setProperty("--cgm-team-color", color);
}

function buildSchedule() {
  const table = scheduleTable();
  if (!table || document.querySelector(".cgm-sched")) return null;
  const rows = [...table.querySelectorAll("tr")].map((row) => [...row.children].map(text));
  if (rows.length < 3 || rows[0].length < 2) return null;
  const strip = document.createElement("div");
  strip.className = "cgm-sched";
  strip.setAttribute("aria-label", "Schedule by week");
  for (let at = 0, week = 1; at < rows[0].length; at += 7, week += 1) {
    const days = document.createElement("div");
    days.className = "cgm-week";
    const first = rows[1][at] || "";
    const last = rows[1][Math.min(at + 6, rows[1].length - 1)] || "";
    days.append(Object.assign(document.createElement("span"), {
      className: "cgm-week-title",
      textContent: first && last && first !== last ? `Week ${week} · ${first}–${last}` : `Week ${week}`,
    }));
    const grid = document.createElement("div");
    grid.className = "cgm-week-days";
    rows[0].slice(at, at + 7).forEach((day, off) => {
      grid.append(dayCard(day, rows[1][at + off] || "", rows[2][at + off] || ""));
    });
    days.append(grid);
    strip.append(days);
  }
  table.classList.add("cgm-sched-src");
  table.before(strip);
  return strip;
}

// The stat toggles read as one mess: a submit, bare checkboxes and labels in
// a row. Group them with titles so each control's job is visible. Inputs move
// with their labels, so the postbacks keep working.
function toggleGroup(input) {
  if (input.type === "submit") return "Defaults";
  return /pergame|total|per36/i.test(input.id || input.name || "") ? "Stats" : "Display";
}

function wrapPair(input) {
  const pair = document.createElement("label");
  pair.className = "cgm-toggle";
  const caption = input.type === "submit" ? input : input.nextElementSibling?.tagName === "LABEL" ? input.nextElementSibling : null;
  input.before(pair);
  pair.append(input);
  if (caption && caption !== input) pair.append(caption);
  if (input.type === "checkbox") pair.classList.toggle("cgm-on", input.checked);
  return pair;
}

function buildStatToggles(anchor) {
  const host = anchor?.parentElement;
  if (!host || document.querySelector(".cgm-toggles")) return null;
  const bar = document.createElement("div");
  bar.className = "cgm-toggles";
  const boxes = {};
  for (const title of ["Defaults", "Stats", "Display"]) {
    const wrap = document.createElement("div");
    wrap.className = "cgm-toggle-group";
    wrap.append(Object.assign(document.createElement("span"), { className: "cgm-toggle-title", textContent: title }));
    boxes[title] = wrap;
  }
  for (const input of [...host.querySelectorAll("input")]) {
    boxes[toggleGroup(input)].append(wrapPair(input));
  }
  for (const wrap of Object.values(boxes)) {
    if (wrap.querySelector(".cgm-toggle")) bar.append(wrap);
  }
  if (!bar.children.length) return null;
  host.before(bar);
  if (!text(host)) host.remove();
  return bar;
}

// The comments thread shows five cards inline; the rest wait in a hidden
// store until "View all" opens the overlay. Nodes move, never clones, so the
// vote and reply postbacks keep working.
const SHOWN_COMMENTS = 5;

function commentSpots(box) {
  const cards = [...box.querySelectorAll(".comment-card")];
  if (box.dataset.cgmComments || cards.length <= SHOWN_COMMENTS) return null;
  box.dataset.cgmComments = "1";
  return cards.map((card) => ({ card, parent: card.parentNode, next: card.nextSibling }));
}

function buildSheet(count, opener, onClose) {
  const overlay = document.createElement("div");
  overlay.className = "cgm-overlay";
  overlay.hidden = true;
  const sheet = document.createElement("div");
  sheet.className = "cgm-sheet";
  sheet.setAttribute("role", "dialog");
  sheet.setAttribute("aria-modal", "true");
  sheet.setAttribute("aria-label", "All comments");
  const head = document.createElement("div");
  head.className = "cgm-sheet-head";
  head.append(Object.assign(document.createElement("span"), { className: "cgm-sheet-title", textContent: `All comments (${count})` }));
  const close = Object.assign(document.createElement("button"), { type: "button", className: "cgm-sheet-close", textContent: "Close" });
  head.append(close);
  const list = document.createElement("div");
  list.className = "cgm-sheet-list";
  sheet.append(head, list);
  overlay.append(sheet);
  document.body.append(overlay);

  const show = (open) => {
    overlay.hidden = !open;
    document.documentElement.classList.toggle("cgm-lock", open);
    if (open) close.focus();
    else opener.focus();
  };
  const hide = () => { onClose(); show(false); };
  opener.addEventListener("click", () => show(true));
  close.addEventListener("click", hide);
  overlay.addEventListener("click", (event) => { if (event.target === overlay) hide(); });
  document.addEventListener("keydown", (event) => { if (event.key === "Escape" && !overlay.hidden) hide(); });
  return { show, list };
}

function buildComments() {
  if (document.querySelector(".cgm-comments-all")) return null;
  const box = document.querySelector("#commentsCollapseId-content");
  const spots = box && commentSpots(box);
  if (!spots) return null;
  const store = document.createElement("div");
  store.className = "cgm-comment-store";
  store.hidden = true;
  box.append(store);
  const cards = spots.map((spot) => spot.card);
  const open = document.createElement("button");
  open.type = "button";
  open.className = "cgm-comments-all";
  open.textContent = `View all ${cards.length} comments`;
  spots[SHOWN_COMMENTS - 1].parent.insertBefore(open, spots[SHOWN_COMMENTS - 1].next);
  const sheet = buildSheet(cards.length, open, () => {
    spots.slice(0, SHOWN_COMMENTS).forEach(({ card, parent, next }) => {
      parent.insertBefore(card, parent.contains(next) ? next : null);
    });
    spots.slice(SHOWN_COMMENTS).forEach(({ card }) => store.append(card));
  });
  spots.slice(SHOWN_COMMENTS).forEach(({ card }) => store.append(card));
  open.addEventListener("click", () => {
    sheet.list.append(...cards);
    sheet.show(true);
  });
  return open;
}

function buildPlayer() {
  if (document.querySelector(".cgm-hero")) return;
  const badge = document.querySelector(".player-stat-badge");
  const h1 = document.querySelector(".page-header h1") || document.querySelector("h1");
  if (!badge || !h1) return;
  const box = badge.closest(".flat-container");

  const { hero, buttons } = buildHero(h1, badge);
  const toolbox = buildToolbox();
  box?.before(hero);
  if (toolbox) hero.after(toolbox);
  dedupeWatch(buttons);
  badge.remove();
  if (box && !text(box)) box.remove();

  buildSchedule();
  buildComments();
  const toggles = [...document.querySelectorAll(".ml-2")].find((el) => el.querySelector('input[type="checkbox"]'));
  if (toggles) buildStatToggles(toggles);
}
return { buildPlayer };
})();

// ---- src/bbm-tiers.js
const { buildTiers } = (() => {
// Drafting Tiers renders every tier with its commentary and players, which is
// a very long page. Fold each tier to one row (name plus a player preview) and
// keep BBM's own position tabs, search and jump buttons working.


function buildTiers() {
  const root = document.querySelector(".drafting-tiers");
  if (!root) return;
  const tiers = () => [...root.querySelectorAll(".dt-tier")];
  const toggle = (tier, folded) => tier.classList.toggle("cgm-folded", folded);

  const seen = new Set();
  for (const tier of tiers()) {
    const head = tier.querySelector(".dt-tier-head");
    const names = [...tier.querySelectorAll(".dt-player")].map((player) => player.dataset.dtName).filter(Boolean);
    const preview = Object.assign(document.createElement("span"), { className: "cgm-preview", textContent: names.join(" · ") });
    head?.append(preview);
    head?.addEventListener("click", (event) => { if (!event.target.closest("a")) toggle(tier, !tier.classList.contains("cgm-folded")); });
    // The first tier of each position list starts open; the rest wait.
    const position = tier.dataset.dtPosition || "";
    toggle(tier, seen.has(position));
    seen.add(position);
  }

  clamp(root.querySelector(".dt-summary"));

  const all = Object.assign(document.createElement("button"), { type: "button", className: "cgm-seg-btn cgm-tier-all", textContent: "Expand all" });
  all.addEventListener("click", () => {
    const open = all.textContent === "Expand all";
    tiers().forEach((tier) => toggle(tier, !open));
    all.textContent = open ? "Collapse all" : "Expand all";
  });
  root.querySelector(".dt-toolbar")?.append(all);

  // Jumping to a folded tier must show it.
  root.addEventListener("click", (event) => {
    const jump = event.target.closest(".dt-jump-btn");
    if (!jump) return;
    const tier = root.querySelector(`#DraftingTiers-tier-${jump.dataset.dtJump}`);
    if (!tier) return;
    toggle(tier, false);
    setTimeout(() => tier.scrollIntoView({ block: "start" }), 0);
  });
  // Searching has to see every player.
  root.querySelector(".dt-search")?.addEventListener("input", (event) => {
    if (event.target.value) tiers().forEach((tier) => toggle(tier, false));
  });
}
return { buildTiers };
})();

// ---- src/bbm-page.js
(() => {
// Entry point for the Basketball Monster redesign. The theme and layout work
// is split by component; this decides which pieces a page gets.













const page = (window.__cgmPage || location.pathname.split("/").pop() || "default").replace(/\.aspx$/i, "").toLowerCase() || "default";

// One broken step must not take the rest of the page down with it.
function step(name, work) {
  try { work(); } catch (error) {
    console.error(`ClutchGM redesign step "${name}" failed`, error);
    (window.__cgmErrors ||= []).push(`${name}: ${error.message}`);
  }
}

function run() {
  document.documentElement.classList.add("cgm-bbm");
  document.documentElement.classList.add(`cgm-page-${page}`);
  step("appbar", buildAppBar);
  step("controlbar", buildControlBar);
  if (page === "default" || page === "") step("home", buildHome);
  if (page === "playernews") step("news", buildNewsPage);
  if (page === "depthcharts") step("depth", buildDepth);
  if (page === "positiontiers") step("tiers", buildTiers);
  if (page === "playerinfo") step("player", buildPlayer);
  step("notices", foldNotices);
  step("status", () => {
    // News cards take their tint from the status badge colour.
    for (const badge of document.querySelectorAll(".news-card-test-status-corner")) {
      badge.closest(".news-card")?.style.setProperty("--cgm-status", badge.style.backgroundColor);
    }
  });
  step("boards", buildBoards);
  step("images", () => enhanceAll());
  step("bylines", () => buildBylines());

  // Colour fixes depend on which stylesheet is live, so they wait for it, then
  // look once more for late-rendered pieces.
  const paint = () => { step("paint", paintBoards); step("legibility", fixLegibility); };
  if (document.readyState === "complete") paint();
  else addEventListener("load", paint, { once: true });
  setTimeout(paint, 2000);
  step("theme", () => onThemeChange(() => { applyHeat(); fixLegibility(); }));
}

if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", run, { once: true });
else run();
})();
